#include <csBlockMatrix/DenseMatrixBlock_impl.hpp>
#include <csBlockMatrix/SparsityPattern.hpp>

#include "csNelson/DoubleSectionHessian.hpp"

static constexpr int secUSizeFix = 6;
static constexpr int secVSizeFix = 3;

template <int secUType, int secVType>
class SecType {
public:
  static constexpr int secUSize = secUSizeFix;
  static constexpr int secVSize = secVSizeFix;
};

template <int secVType>
class SecType<csBlockMatrix::Variable, secVType> {
public:
  static const std::vector<int> secUSize;
  static constexpr int secVSize = secVSizeFix;
};
template <int secVType>
const std::vector<int> SecType<csBlockMatrix::Variable, secVType>::secUSize = {6, 5, 7, 4, 8}; // sum = 30

template <int secUType>
class SecType<secUType, csBlockMatrix::Variable> {
public:
  static constexpr int secUSize = secUSizeFix;
  static const std::vector<int> secVSize;
};
template <int secUType>
const std::vector<int> SecType<secUType, csBlockMatrix::Variable>::secVSize = {3, 1, 4}; // sum = 9

template <>
class SecType<csBlockMatrix::Variable, csBlockMatrix::Variable> {
public:
  static const std::vector<int> secUSize;
  static const std::vector<int> secVSize;
};
const std::vector<int> SecType<csBlockMatrix::Variable, csBlockMatrix::Variable>::secUSize = {6, 5, 7, 4, 8}; // sum = 30
const std::vector<int> SecType<csBlockMatrix::Variable, csBlockMatrix::Variable>::secVSize = {3, 1, 4};       // sum = 9

